using MediatR; using Microsoft.AspNetCore.Http; using Microsoft.AspNetCore.Routing; namespace JTradeERP.Application.Features.MasterData.UnitsOfMeasure.DeleteUnitOfMeasure; public static class DeleteUnitOfMeasureEndpoint {public static void Map(IEndpointRouteBuilder e)=>e.MapDelete("/units-of-measure/{id:guid}",async(Guid id,ISender s,CancellationToken ct)=>{await s.Send(new DeleteUnitOfMeasureCommand(id),ct);return Results.NoContent();});}
